if (joy2_btn == 0) {
    box_start = 0;                        //reset box coordinates
    box_center = 0;
    box_end = 0;

    pos[4] = min_pos[4];  
    arm_servos[4].write(pos[4]);          // Rotate all the way to the min

    while (pos[4] < max_pos[4]) {
       pos[4]++;
       arm_servos[4].write(pos[4]);       // Incremental servo movement
       distance = getDistance();
       if (distance > 0 && distance <10 && box_start == 0) {
          box_start = pos[4];
       }
       if ((distance >10 || distance == 0) && box_start > 0 && box_center == 0) {
          if ((pos[4] - box_start) > 10) {
             box_end = pos[4];
             box_center = (box_end - box_start)/2 + box_start;
          } else {
             box_start = 0;
          }
       }
       delay(100);
    }
}
